import { HierarchyRectangularNode } from '@visx/hierarchy/lib/types';
import { InternalTreeMapLeafNode } from './internal.js';
import { LegendItem } from '../../core/components/legend/categorical/types/legend.js';
import type { MouseCoordinate } from '../../core/types/overlays.js';
export interface TreeMapState {
    /** List of categories (nodes of depth 1) which are shown in the treemap. */
    groupsSelected: LegendItem[];
    /** Id of highlighted nodes (category node - depth 1). */
    highlightedItems?: LegendItem[];
    /** The current tooltip state. */
    tooltip: {
        /** Whether the tooltip is currently visible. */
        visible: boolean;
        /** Is tooltip pinned - stays in place, does not change content on hovering over other items. */
        pinned: boolean;
        content?: HierarchyRectangularNode<InternalTreeMapLeafNode>;
        position?: MouseCoordinate;
    };
    overlay: {
        mouseInBounds: boolean;
    };
    /** An array containing all visible nodes. */
    visibleNodes: HierarchyRectangularNode<InternalTreeMapLeafNode>[];
}
